import {createGame,step,chooseUpgrade,talents} from './engine.mjs';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d',{alpha:false}),overlay=$('#overlay');
let g=createGame(),last=0,acc=0,hudClock=0,screenStatus='ready',width=1000,height=625,dpr=1,viewScale=1,keys=new Set(),pointer=null,touch={x:0,y:0},best=0,sound=false,audio,hitKills=0,lastHealth=100;
try{best=Number(localStorage.getItem('emberfall-best'))||0}catch{}const format=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;$('#record').textContent=format(best);
const spriteData={
 hero:['......ggg.....','.....ggggg....','.....gsssg....','......ss......','....tttttt....','...ttcttctt..b','...tttttttt..b','...tttddttt..b','....tttttt...b','....tttttt...b','....tttttt...b','....tttttt....','.....bb.bb....','.....bb.bb....'],
 skeleton:['....mmmm....','...mssssm...','...skskks...','...ssssss...','....sks.....','.....s......','..mmssssmm..','..s..ss..s..','..s..ss..s..','....ssss....','....s..s....','...ss..ss...'],
 bat:['p.........p','pp.......pp','pvp.....pvp','pvvpp.ppvvp','.pvvvvvvvp.','..pvevevp..','...pvvvp...','....ppp....'],
 brute:['....mmmmmm....','..mmmmmmmmmm..','..mmsssksmmm..','...mssskssm...','....mmssmm....','..mmmmmmmmmm..','.mmmmbbbbmmmm.','mmmmbbbbdbmmmm','mmmmbbbbbbmmmm','.mmmmbbbbmmmm.','..mmmmmmmmmm..','...mmm..mmm...','...mmm..mmm...','...bbb..bbb...'],
 wraith:['.....ppp.....','....pvvvp....','...pvvvvvp...','...vvevevv...','...vvvvvvv...','....vvvvv....','...vvvvvvv...','..vvvvvvvvv..','..vvvvpvvvv..','.vvvpvvvpvvv.','..vp..vp..vp.'],
 warden:['......cccc......','....ccggggcc....','...cggggggggc...','...gssskksssg...','....sskkksss....','.....gggggg.....','..ccggggggggcc..','.ccgggbbbbgggcc.','ccgggbbddbbgggcc','ccgggbbddbbgggcc','.cggggbbbbggggc.','..gggggggggggg..','...gggggggggg...','....gggggggg....','....ggg..ggg....','....bbb..bbb....']
};
const palette={g:'#bd985c',s:'#d5cfad',k:'#263f30',t:'#6eaa91',c:'#e5c781',d:'#384e40',b:'#4c4633',m:'#657f4a',p:'#544566',v:'#9b83ae',e:'#e8cdaa'};
const sprites={};for(const [name,rows]of Object.entries(spriteData)){const c=document.createElement('canvas');c.width=rows[0].length;c.height=rows.length;const x=c.getContext('2d');rows.forEach((row,y)=>[...row].forEach((ch,i)=>{if(ch!=='.'){x.fillStyle=palette[ch];x.fillRect(i,y,1,1)}}));sprites[name]=c}
function sprite(c,name,x,y,size,flip=1,flash=false){const s=sprites[name];c.save();c.translate(Math.round(x),Math.round(y));c.scale(flip,1);c.imageSmoothingEnabled=false;c.drawImage(s,-s.width*size/2,-s.height*size,s.width*size,s.height*size);if(flash){c.globalCompositeOperation='source-atop';}c.restore()}
const portrait=$('#portrait').getContext('2d');sprite(portrait,'hero',48,82,4);
function tone(freq=330,length=.06,type='sine',volume=.025){if(!sound)return;try{audio??=new AudioContext();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.6,audio.currentTime+length);v.gain.setValueAtTime(volume,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+length)}catch{}}
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'♪ ON':'♪ OFF';$('#sound').setAttribute('aria-label',sound?'Disable sound':'Enable sound');if(sound)tone(520,.15)};
function announce(text){$('#announcement').textContent=text}
function start(){g=createGame();g.status='playing';keys.clear();touch={x:0,y:0};acc=0;last=performance.now();screenStatus='';hitKills=0;lastHealth=100;overlay.classList.add('hidden');$('#pause').disabled=false;canvas.focus();updateBuild();updateHUD();tone(540,.14)}
$('#start').onclick=start;
function pause(){if(g.status==='playing'){g.status='paused';keys.clear();touch={x:0,y:0};pointer=null;$('#joystick').classList.remove('active')}else if(g.status==='paused'){g.status='playing';last=performance.now();canvas.focus()}renderStatus()}
$('#pause').onclick=pause;
function panel(html){overlay.innerHTML=html;overlay.classList.remove('hidden')}
function renderStatus(){if(screenStatus===g.status)return;screenStatus=g.status;updateHUD();$('#pause').textContent=g.status==='paused'?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',g.status==='paused'?'Resume game':'Pause game');if(g.status==='playing'){overlay.classList.add('hidden');return}if(g.status==='levelup'){tone(740,.25,'triangle');panel(`<div class="level-screen"><span class="eyebrow">LEVEL ${g.level} REACHED</span><h2>The ember grows stronger.</h2><p>Choose one passive ability. All effects stack. The wilds can wait.</p><div class="choices">${g.choices.map((id,i)=>{const t=talents.find(t=>t.id===id);return `<button class="choice" data-talent="${id}"><span class="choice-rank">${i+1} · RANK ${(g.build[id]||0)+1}</span><span class="choice-icon">${t.icon}</span><small>${t.type}</small><strong>${t.name}</strong><p>${t.description}</p></button>`}).join('')}</div><small class="choose-note">CHOOSE WITH A CLICK, A TAP, OR KEYS 1 / 2 / 3</small></div>`);announce(`Level ${g.level}. Choose one of three passive abilities.`);overlay.querySelector('.choice')?.focus()}else if(g.status==='paused'){panel('<div class="start-screen"><span class="chapter">THE WILDS ARE WAITING</span><div class="title-emblem">✧</div><h2>A moment<br>by the fire.</h2><p>Your run is paused. Take your time.</p><button id="resume" class="gold-button">Return to the wilds →</button></div>');$('#resume').onclick=pause;}else if(g.status==='dead'){const record=g.time>best;if(record){best=g.time;try{localStorage.setItem('emberfall-best',String(best))}catch{}$('#record').textContent=format(best)}panel(`<div class="start-screen"><span class="chapter">${record?'A NEW PERSONAL BEST':'THE EMBER FADES'}</span><div class="title-emblem">✧</div><h2>Even embers<br>rise again.</h2><div class="run-results"><div><span>SURVIVED</span><b>${format(g.time)}</b></div><div><span>DEFEATED</span><b>${g.kills}</b></div><div><span>LEVEL</span><b>${g.level}</b></div></div><p>A different path. A different build.<br>One more run?</p><button id="restart" class="gold-button">Carry the flame again →</button></div>`);$('#restart').onclick=start;$('#pause').disabled=true;announce(`Run complete. Survived ${format(g.time)}, defeated ${g.kills} enemies.`);tone(140,.5,'triangle')}}
overlay.addEventListener('click',e=>{const b=e.target.closest('[data-talent]');if(b&&chooseUpgrade(g,b.dataset.talent)){keys.clear();screenStatus='';updateBuild();updateHUD();renderStatus();canvas.focus();tone(850,.1)}});
function updateBuild(){const entries=Object.entries(g.build);$('#ability-count').textContent=entries.length;$('#build').innerHTML=entries.length?entries.map(([id,rank])=>{const t=talents.find(t=>t.id===id);return `<div class="ability-item" title="${t.description}"><span class="ability-icon">${t.icon}</span><div class="ability-info"><strong>${t.name}</strong><small>${t.type}</small></div><b>×${rank}</b></div>`}).join(''):'<div class="empty-build"><span>✧</span><p>Your story is unwritten.</p><small>Defeat enemies to earn XP.<br>Each level offers 3 passive abilities.<br>Choose one. Shape your survival.</small></div>'}
function updateHUD(){$('#time').textContent=format(g.time);$('#kills').textContent=g.kills;$('#level').textContent=String(g.level).padStart(2,'0');$('#health-fill').style.width=`${g.health/g.stats.maxHealth*100}%`;$('#health-fill').style.background=g.health/g.stats.maxHealth<.3?'#de8972':'#a5bd82';$('#health-text').textContent=`${Math.ceil(g.health)} / ${g.stats.maxHealth}`;$('#xp-level').textContent=`LVL ${g.level}`;$('#xp-fill').style.width=`${Math.min(100,g.xp/g.nextXP*100)}%`;$('#xp-count').textContent=`${Math.floor(g.xp)} / ${g.nextXP} XP`;$('#damage').textContent=Math.round(g.stats.damage);$('#attack-speed').textContent=(1/Math.max(.06,g.stats.interval)).toFixed(1);$('#move-speed').textContent=Math.round(g.stats.speed);$('#regeneration').textContent=`${g.stats.regen.toFixed(1)} /s`;const phases=['NIGHTFALL I','NIGHTFALL II','THE GATHERING','THE LONG DARK'];$('#danger').textContent='/ '+(phases[Math.floor(g.time/60)]||`THE LONG DARK ${Math.floor(g.time/60)-2}`);$('#boss-alert').hidden=!g.effects.some(e=>e.kind==='elite')}
const movementKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowLeft','ArrowDown','ArrowRight'];document.addEventListener('keydown',e=>{if($('#help-dialog').open)return;if(movementKeys.includes(e.code)){if(g.status==='playing'){e.preventDefault();keys.add(e.code)}}if(['Escape','KeyP'].includes(e.code)&&!e.repeat){e.preventDefault();pause()}if(g.status==='levelup'&&['Digit1','Digit2','Digit3'].includes(e.code)){const id=g.choices[Number(e.code.at(-1))-1];if(chooseUpgrade(g,id)){keys.clear();screenStatus='';updateBuild();updateHUD();renderStatus();canvas.focus()}}});document.addEventListener('keyup',e=>keys.delete(e.code));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&g.status==='playing')pause()});window.addEventListener('blur',()=>{keys.clear();if(g.status==='playing')pause()});
let helpPaused=false;$('#help').onclick=()=>{helpPaused=g.status==='playing';if(helpPaused)pause();$('#help-dialog').showModal()};const closeHelp=()=>$('#help-dialog').close();$('#help-close').onclick=closeHelp;$('#help-dialog .close').onclick=closeHelp;$('#help-dialog').addEventListener('close',()=>{if(helpPaused&&g.status==='paused')pause()});
canvas.addEventListener('pointerdown',e=>{if(g.status!=='playing')return;e.preventDefault();canvas.focus();if(e.pointerType==='mouse')return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);const r=$('#arena').getBoundingClientRect();$('#joystick').style.left=`${e.clientX-r.left-42}px`;$('#joystick').style.top=`${e.clientY-r.top-42}px`;$('#joystick').classList.add('active')});canvas.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;const x=e.clientX-pointer.x,y=e.clientY-pointer.y,d=Math.hypot(x,y),r=Math.max(35,d);touch={x:x/r,y:y/r};$('#stick').style.transform=`translate(${x/r*24}px,${y/r*24}px)`});function release(e){if(pointer?.id!==e.pointerId)return;pointer=null;touch={x:0,y:0};$('#joystick').classList.remove('active');$('#stick').style.transform='none'}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);viewScale=Math.min(1,r.width/800);width=r.width/viewScale;height=r.height/viewScale;canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.imageSmoothingEnabled=false}new ResizeObserver(resize).observe(canvas);
function hash(x,y){let n=Math.imul(x,374761393)+Math.imul(y,668265263);n=(n^(n>>>13));return (Math.imul(n,1274126177)>>>0)/4294967296}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function terrain(){const left=g.x-width/2-100,right=g.x+width/2+100,top=g.y-height/2-100,bottom=g.y+height/2+100;ctx.fillStyle='#1c3026';ctx.fillRect(left,top,right-left,bottom-top);for(let tx=Math.floor(left/64);tx<right/64;tx++)for(let ty=Math.floor(top/64);ty<bottom/64;ty++){const r=hash(tx,ty),x=tx*64,y=ty*64;ctx.fillStyle=r>.6?'#21372a':'#1e3227';ctx.fillRect(x,y,64,64);for(let k=0;k<4;k++){const a=hash(tx*7+k,ty*3),b=hash(tx*3,ty*7+k);ctx.fillStyle=k%2?'#40553a66':'#65714a33';ctx.fillRect(x+a*60,y+b*60,2,4);ctx.fillRect(x+a*60+3,y+b*60-2,2,3)}if(r>.90){ellipse(x+25,y+33,25,8,'#101f1877');ctx.fillStyle='#344639';ctx.fillRect(x+11,y+16,25,14);ctx.fillStyle='#4b5b45';ctx.fillRect(x+15,y+10,19,14);ctx.fillStyle='#607255';ctx.fillRect(x+17,y+10,12,3);ctx.fillStyle='#233b2c';ctx.fillRect(x+9,y+27,32,4)}else if(r<.055){ellipse(x+28,y+42,22,7,'#0e1c1580');ctx.fillStyle='#465549';ctx.fillRect(x+21,y+17,15,23);ctx.fillRect(x+18,y+20,21,4);ctx.fillStyle='#73806a';ctx.fillRect(x+23,y+16,11,3);ctx.fillStyle='#263b2c';ctx.fillRect(x+27,y+22,3,12);ctx.fillRect(x+24,y+26,9,2)}else if(r>.81&&r<.85){ctx.fillStyle='#a29364';ctx.fillRect(x+15,y+22,3,4);ctx.fillRect(x+23,y+18,3,4);ctx.fillStyle='#c4ad79';ctx.fillRect(x+12,y+20,9,3);ctx.fillRect(x+20,y+16,9,3)}}}
function tree(x,y,r){ellipse(x,y+8,r*.8,12,'#0a19137a');ctx.fillStyle='#2d3827';ctx.fillRect(x-5,y-r,10,r+4);const layers=[['#13291f',0,0],['#1b3427',-r*.2,-r*.23],['#24402c',r*.12,-r*.42],['#2b4830',-r*.1,-r*.62]];for(const [c,ox,oy]of layers){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x+ox,y-r+oy-r*.35);ctx.lineTo(x+ox-r*.75,y+oy);ctx.lineTo(x+ox+r*.75,y+oy);ctx.closePath();ctx.fill()}}
function draw(now){if(!width)return;ctx.setTransform(dpr*viewScale,0,0,dpr*viewScale,0,0);ctx.clearRect(0,0,width,height);ctx.save();ctx.translate(Math.round(width/2-g.x),Math.round(height/2-g.y));terrain();
 // Trees are scenery rather than collision obstacles; open paths leave room to kite.
 const trees=[];for(let x=Math.floor((g.x-width/2-110)/240);x<(g.x+width/2+110)/240;x++)for(let y=Math.floor((g.y-height/2-110)/230);y<(g.y+height/2+150)/230;y++){const r=hash(x+75,y-23);if(r>.48)trees.push({x:x*240+hash(x,y)*120,y:y*230+hash(y,x)*90,r:40+r*30})}
const entities=[...g.enemies.map(e=>({type:'enemy',e,x:e.x,y:e.y})),{type:'hero',x:g.x,y:g.y+14},...trees.map(t=>({...t,type:'tree'}))].sort((a,b)=>a.y-b.y);
for(const ent of entities){if(Math.abs(ent.x-g.x)>width/2+100||Math.abs(ent.y-g.y)>height/2+160)continue;if(ent.type==='tree'){tree(ent.x,ent.y,ent.r);continue}if(ent.type==='hero'){const pulse=Math.sin(now*.002)*.1+.9;const glow=ctx.createRadialGradient(g.x,g.y,4,g.x,g.y,83);glow.addColorStop(0,`rgba(221,179,97,${.13*pulse})`);glow.addColorStop(1,'#dcb66b00');ctx.fillStyle=glow;ctx.fillRect(g.x-85,g.y-85,170,170);ellipse(g.x,g.y+13,16,6,'#071b1399');ctx.globalAlpha=g.invulnerable>0&&Math.floor(now/65)%2?.45:1;const walk=keys.size||Math.hypot(touch.x,touch.y)>.1?Math.sin(g.time*15)*2:Math.sin(now*.003);sprite(ctx,'hero',g.x,g.y+15+walk,2.5,g.facing);ctx.fillStyle='#f3ce7c';ctx.shadowColor='#f7c661';ctx.shadowBlur=10;ctx.fillRect(g.x+g.facing*16,g.y-16+walk,4,5);ctx.shadowBlur=0;ctx.globalAlpha=1;continue}const e=ent.e;ellipse(e.x,e.y+e.r*.6,e.r*.9,e.r*.35,'#081c1580');const bob=Math.sin(g.time*(e.type===1?18:7)+e.id)*2;const size=e.type===4?4:e.type===2?3:2.3;sprite(ctx,['skeleton','bat','brute','wraith','warden'][e.type],e.x,e.y+e.r*.8+bob,size,e.x>g.x?-1:1);if(e.hit>0){ctx.globalAlpha=e.hit*3;ellipse(e.x,e.y-e.r*.3,e.r,e.r,'#f8e9b6');ctx.globalAlpha=1}if(e.hp<e.maxHP||e.type===4){const bw=e.type===4?52:24;ctx.fillStyle='#102019';ctx.fillRect(e.x-bw/2,e.y-e.r-15,bw,3);ctx.fillStyle=e.type===4?'#d9aa6b':'#9eac72';ctx.fillRect(e.x-bw/2,e.y-e.r-15,bw*Math.max(0,e.hp/e.maxHP),3)}}
for(const b of g.bullets){ctx.strokeStyle='#d5b56866';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(b.x-b.vx*.027,b.y-b.vy*.027);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.fillStyle='#ffe3a0';ctx.shadowColor='#edc975';ctx.shadowBlur=8;ctx.fillRect(b.x-3,b.y-3,6,6);ctx.shadowBlur=0}
for(let i=0;i<g.stats.orbits;i++){const a=g.time*2.5+i*Math.PI*2/g.stats.orbits,x=g.x+Math.cos(a)*g.stats.radius,y=g.y+Math.sin(a)*g.stats.radius;ctx.strokeStyle='#a8cbbb18';ctx.lineWidth=1;ctx.beginPath();ctx.arc(g.x,g.y,g.stats.radius,0,Math.PI*2);ctx.stroke();ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#b8d8ca';ctx.shadowColor='#a5d8c6';ctx.shadowBlur=9;ctx.fillRect(-3,-11,6,22);ctx.fillStyle='#769888';ctx.fillRect(-7,3,14,3);ctx.restore()}
for(const e of g.effects){if(e.kind==='elite')continue;const p=1-e.life/e.max;ctx.globalAlpha=1-p;ctx.strokeStyle=e.color;ctx.fillStyle=e.color;if(e.kind==='nova'){ctx.lineWidth=4*(1-p);ctx.beginPath();ctx.arc(e.x,e.y,e.r*p,0,Math.PI*2);ctx.stroke()}else for(let j=0;j<7;j++){const a=j/7*Math.PI*2;ctx.fillRect(e.x+Math.cos(a)*p*e.r*2,e.y+Math.sin(a)*p*e.r*2,3,3)}ctx.globalAlpha=1}
ctx.textAlign='center';ctx.font='bold 11px monospace';for(const n of g.numbers){ctx.globalAlpha=Math.min(1,n.life*3);ctx.fillStyle=n.color;ctx.fillText(n.text,Math.round(n.x),Math.round(n.y));ctx.globalAlpha=1}ctx.restore();const vignette=ctx.createRadialGradient(width/2,height/2,Math.min(width,height)*.18,width/2,height/2,Math.max(width,height)*.65);vignette.addColorStop(0,'#06160f00');vignette.addColorStop(1,'#06130d99');ctx.fillStyle=vignette;ctx.fillRect(0,0,width,height);if(g.invulnerable>.4){ctx.fillStyle='#b6422817';ctx.fillRect(0,0,width,height)}
}
function frame(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(g.status==='playing'){acc+=dt;const input={x:(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x,y:(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.y};let count=0;while(acc>=1/60&&count++<6&&g.status==='playing'){step(g,1/60,input);acc-=1/60}if(g.kills>hitKills){tone(380+Math.random()*90,.05,'triangle',.015);hitKills=g.kills}if(g.health<lastHealth)tone(95,.12,'sawtooth',.02);lastHealth=g.health;hudClock+=dt;if(hudClock>.12){updateHUD();hudClock=0}}else acc=0;renderStatus();draw(now);requestAnimationFrame(frame)}requestAnimationFrame(frame);
// Static preview: actual renderer and hero, with no enemies until the run starts.
updateHUD();
